#include <vector>

class Solution {
    int get_depth(int x) {
        if (x <= 1) return 0;
        int c = 0;
        int temp = x;
        while (temp) {
            c += (temp & 1);
            temp >>= 1;
        }
        return 1 + get_depth(c);
    }
public:
    std::vector<int> popcountQueries(std::vector<int>& nums, std::vector<std::vector<int>>& queries) {
        std::vector<int> arr;
        arr.reserve(nums.size());
        for (int x : nums) arr.push_back(get_depth(x));

        std::vector<int> ans;
        for (const auto& q : queries) {
            int t = q[0];
            if (t == 1) {
                int l = q[1], r = q[2], k = q[3];
                int cnt = 0;
                for (int i = l; i <= r; ++i) {
                    if (arr[i] == k) cnt++;
                }
                ans.push_back(cnt);
            } else if (t == 2) {
                int idx = q[1], val = q[2];
                arr[idx] = get_depth(val);
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] popcountQueries(int[] nums, int[][] queries) {
        int[] arr = new int[nums.length];
        for (int i = 0; i < nums.length; i++) arr[i] = getDepth(nums[i]);

        List<Integer> res = new ArrayList<>();
        for (int[] q : queries) {
            int t = q[0];
            if (t == 1) {
                int l = q[1], r = q[2], k = q[3];
                int cnt = 0;
                for (int i = l; i <= r; i++) {
                    if (arr[i] == k) cnt++;
                }
                res.add(cnt);
            } else if (t == 2) {
                int idx = q[1], val = q[2];
                arr[idx] = getDepth(val);
            }
        }

        int[] ans = new int[res.size()];
        for (int i = 0; i < res.size(); i++) ans[i] = res.get(i);
        return ans;
    }

    private int getDepth(int x) {
        if (x <= 1) return 0;
        return 1 + getDepth(Integer.bitCount(x));
    }
}

/**
 * @param {number[]} nums
 * @param {number[][]} queries
 * @return {number[]}
 */
var popcountQueries = function(nums, queries) {
    const getDepth = (x) => {
        if (x <= 1) return 0;
        let c = 0;
        let temp = x;
        while (temp > 0) {
            c += (temp & 1);
            temp >>= 1;
        }
        return 1 + getDepth(c);
    };

    const arr = nums.map(getDepth);
    const ans = [];

    for (const q of queries) {
        const t = q[0];
        if (t === 1) {
            const [, l, r, k] = q;
            let cnt = 0;
            for (let i = l; i <= r; i++) {
                if (arr[i] === k) cnt++;
            }
            ans.push(cnt);
        } else if (t === 2) {
            const [, idx, val] = q;
            arr[idx] = getDepth(val);
        }
    }

    return ans;
};
